from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    field_validator,
)

from app.schemas.missing_field import MissingField


class GeneratedCardContent(BaseModel):
    """Content generated by LLM."""

    model_config = ConfigDict(
        extra="forbid",
        str_strip_whitespace=True,
    )

    seo_title: str = Field(
        min_length=1,
        max_length=70,
    )

    seo_description: str = Field(
        min_length=800,
        max_length=1200,
    )

    search_queries: list[str] = Field(
        min_length=3,
        max_length=5,
    )

    commercial_block: str = Field(
        min_length=1,
    )

    @field_validator("search_queries")
    @classmethod
    def validate_search_queries(
        cls,
        value: list[str],
    ) -> list[str]:
        if any(not query for query in value):
            raise ValueError("Search queries cannot be empty")

        if len(set(value)) != len(value):
            raise ValueError("Search queries must be unique")

        return value


class ProductCard(BaseModel):
    """Complete product card returned by application."""

    model_config = ConfigDict(
        extra="forbid",
        str_strip_whitespace=True,
    )

    seo_title: str = Field(
        min_length=1,
        max_length=70,
    )

    seo_description: str = Field(
        min_length=800,
        max_length=1200,
    )

    specifications: dict[str, str]

    search_queries: list[str] = Field(
        min_length=3,
        max_length=5,
    )

    commercial_block: str = Field(
        min_length=1,
    )

    missing_fields: list[MissingField] = Field(
        default_factory=list,
    )

    warnings: list[str] = Field(
        default_factory=list,
    )
